package com.growercare.shard;

import java.time.Instant;

/**
 * Pure-Java codec for the 64-bit IDs generated by each shard's {@code next_id()} (doc 04 §3):
 * <pre>0 | 41 bits ms since 2026-01-01Z | 6 bits country index | 6 bits shard | 10 bits sequence</pre>
 * Decoding needs no database call, which is what lets any service route a request by ID alone.
 */
public final class IdCodec {

    /** 2026-01-01T00:00:00Z in epoch milliseconds. Must equal {@code our_epoch} in the shard migration. */
    public static final long EPOCH_MS = 1_767_225_600_000L;
    public static final int MAX_COUNTRY_IX = 63;
    public static final int MAX_SHARD = 63;
    public static final int MAX_SEQUENCE = 1023;

    private static final int TIME_SHIFT = 22;
    private static final int COUNTRY_SHIFT = 16;
    private static final int SHARD_SHIFT = 10;
    private static final long SIX_BITS = 0x3F;
    private static final long TEN_BITS = 0x3FF;

    private IdCodec() { }

    /** Decoded parts of an ID. */
    public record DecodedId(Instant createdAt, int countryIx, int shardNo, int sequence) { }

    public static DecodedId decode(long id) {
        if (id <= 0) {
            throw new IllegalArgumentException("ID must be positive");
        }
        return new DecodedId(
                Instant.ofEpochMilli((id >>> TIME_SHIFT) + EPOCH_MS),
                (int) ((id >>> COUNTRY_SHIFT) & SIX_BITS),
                (int) ((id >>> SHARD_SHIFT) & SIX_BITS),
                (int) (id & TEN_BITS));
    }

    /** Builds an ID; used by tests and by tools, never to create production IDs (the DB does that). */
    public static long encode(Instant createdAt, int countryIx, int shardNo, int sequence) {
        if (countryIx < 0 || countryIx > MAX_COUNTRY_IX || shardNo < 0 || shardNo > MAX_SHARD
                || sequence < 0 || sequence > MAX_SEQUENCE) {
            throw new IllegalArgumentException("ID component out of range");
        }
        return floor(createdAt) | ((long) countryIx << COUNTRY_SHIFT) | ((long) shardNo << SHARD_SHIFT) | sequence;
    }

    /**
     * Smallest possible ID at the given instant. Used for partition bounds and time-range scans on {@code case_id}.
     * Must agree with {@code ref.id_floor(timestamptz)} in SQL.
     */
    public static long floor(Instant instant) {
        long ms = instant.toEpochMilli() - EPOCH_MS;
        if (ms < 0) {
            throw new IllegalArgumentException("Instant before ID epoch: " + instant);
        }
        return ms << TIME_SHIFT;
    }
}
